template:
stack<int> st;
st.push(value);
int top = st.top();
st.pop();

while (!operators.empty() && precedence(operators.top()) >= precedence(token)) {
    output += operators.top();
    operators.pop();
}

for (int i = n - 1; i >= 0; --i) {
    while (!st.empty() && st.top() <= nums[i]) st.pop();
    answer[i] = st.empty() ? -1 : st.top();
    st.push(nums[i]);
}
